const response = ($json.pm_response || "").trim();
const upperResponse = response.toUpperCase();

let decision = "UNKNOWN";
let instructions = "";

// -------------------------
// APPROVAL
// -------------------------
const approvalPatterns = [
  /^APPROVE[.!]?$/i,
  /^APPROVED[.!]?$/i,
  /^YES[.!]?$/i,
  /^YES,?\s*(APPROVE|APPROVED)[.!]?$/i,
  /^LOOKS GOOD[.!]?$/i,
  /^LOOKS GOOD,?\s*(APPROVED|PLEASE PROCEED)?[.!]?$/i,
  /^LGTM[.!]?$/i,
  /^GO AHEAD[.!]?$/i,
  /^PLEASE PROCEED[.!]?$/i,
  /^NICE[.!]?$/i,
  /^NICE,?\s*(WORK|JOB)?[.!]?$/i
];

if (approvalPatterns.some(pattern => pattern.test(response))) {
  decision = "APPROVED";
}

// -------------------------
// REJECTION
// -------------------------
else if (
  /^REJECT[.!]?$/i.test(response) ||
  /^REJECTED[.!]?$/i.test(response) ||
  /^NOT APPROVED[.!]?$/i.test(response)
) {
  decision = "REJECTED";
}

// -------------------------
// MODIFY / CHANGES
// -------------------------
else if (/^MODIFY\b/i.test(response)) {
  decision = "MODIFY";

  instructions = response
    .replace(/^MODIFY\s*:?\s*/i, "")
    .trim();
}

else if (
  /^MODIFY\b/i.test(response) ||
  /^CHANGE\b/i.test(response) ||
  /^CHANGES?\b/i.test(response) ||
  /^UPDATE\b/i.test(response) ||
  /^UPDATES?\b/i.test(response) ||
  /^MAKE\s+CHANGES?\b/i.test(response) ||
  /^PLEASE\s+MAKE\s+CHANGES?\b/i.test(response) ||
  /^NEEDS?\s+CHANGES?\b/i.test(response) ||
  /^I\s+WANT\s+CHANGES?\b/i.test(response) ||
  /^PLEASE\s+CHANGE\b/i.test(response) ||
  /^PLEASE\s+UPDATE\b/i.test(response)
) {
  decision = "MODIFY";
  instructions = response
    .replace(/^(CHANGE|CHANGES|UPDATE|UPDATES)\s*:?\s*/i, "")
    .trim();
}

// -------------------------
// Return normalized result
// -------------------------
return [
  {
    json: {
      thread_ts: $json.thread_ts,
      pm_response: response,
      decision: decision,
      modification_instructions: instructions
    }
  }
];

const prd = $json.prd_json;

return [
  {
    json: {
      prd: prd
    }
  }
];

const prd = $input.first().json.prd || "";

// ------------------------------------
// HTML escaping
// ------------------------------------
function escapeHtml(text) {
  return String(text ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}


// ------------------------------------
// Basic inline Markdown formatting
// ------------------------------------
function formatInline(text) {

  let value = escapeHtml(text);

  // Bold: **text**
  value = value.replace(
    /\*\*(.*?)\*\*/g,
    "<strong>$1</strong>"
  );

  // Italic: *text*
  value = value.replace(
    /(?<!\*)\*([^*]+)\*(?!\*)/g,
    "<em>$1</em>"
  );

  return value;
}


// ------------------------------------
// Split PRD into lines
// ------------------------------------
const lines = prd
  .replace(/\r\n/g, "\n")
  .replace(/\r/g, "\n")
  .split("\n");

let htmlContent = "";

let inTable = false;
let tableRows = [];


// ------------------------------------
// Flush table
// ------------------------------------
function flushTable() {

  if (!tableRows.length) {
    return;
  }

  htmlContent += `
<table>
  <thead>
    <tr>
      ${tableRows[0]
        .map(cell => `<th>${formatInline(cell)}</th>`)
        .join("")}
    </tr>
  </thead>
  <tbody>
`;

  for (let i = 1; i < tableRows.length; i++) {

    htmlContent += `
    <tr>
      ${tableRows[i]
        .map(cell => `<td>${formatInline(cell)}</td>`)
        .join("")}
    </tr>
`;
  }

  htmlContent += `
  </tbody>
</table>
`;

  tableRows = [];
  inTable = false;
}


// ------------------------------------
// Process lines
// ------------------------------------
for (let i = 0; i < lines.length; i++) {

  const rawLine = lines[i];
  const line = rawLine.trim();

  // ----------------------------------
  // Empty line
  // ----------------------------------
  if (!line) {

    if (inTable) {
      flushTable();
    }

    continue;
  }


  // ----------------------------------
  // Ignore Markdown code fences
  // ----------------------------------
  if (line === "```" || line.startsWith("```")) {
    continue;
  }


  // ----------------------------------
  // Markdown table
  // ----------------------------------
  if (line.includes("|")) {

    let cells = line
      .split("|")
      .map(cell => cell.trim());

    // Remove empty first/last cells
    if (cells[0] === "") {
      cells.shift();
    }

    if (cells[cells.length - 1] === "") {
      cells.pop();
    }

    // Ignore Markdown separator row
    const isSeparator = cells.every(cell =>
      /^:?-{3,}:?$/.test(cell)
    );

    if (isSeparator) {
      continue;
    }

    if (!inTable) {
      inTable = true;
    }

    tableRows.push(cells);

    continue;
  }


  // ----------------------------------
  // Close table if next line isn't table
  // ----------------------------------
  if (inTable) {
    flushTable();
  }


  // ----------------------------------
  // Main PRD title
  // ----------------------------------
  if (
    line
      .replace(/[*#]/g, "")
      .trim()
      .toUpperCase()
      .includes("PRODUCT REQUIREMENTS DOCUMENT")
  ) {

    htmlContent += `
<h1>PRODUCT REQUIREMENTS DOCUMENT</h1>
`;

    continue;
  }


  // ----------------------------------
  // Markdown H1 / H2 / H3
  // ----------------------------------
  const headingMatch = line.match(/^#{1,3}\s+(.+)$/);

  if (headingMatch) {

    const heading = headingMatch[1]
      .replace(/\*\*/g, "")
      .trim();

    htmlContent += `
<h2>${escapeHtml(heading)}</h2>
`;

    continue;
  }


  // ----------------------------------
  // PRD Title
  // **PRD Title**: Healthcare AI...
  // ----------------------------------
  const prdTitleMatch = line.match(
    /^\*\*PRD Title\*\*\s*:?\s*(.*)$/i
  );

  if (prdTitleMatch) {

    htmlContent += `
<h2>PRD Title</h2>
<p>${formatInline(prdTitleMatch[1])}</p>
`;

    continue;
  }


  // ----------------------------------
  // Bullet list
  // ----------------------------------
  if (/^[-*]\s+/.test(line)) {

    const item = line.replace(/^[-*]\s+/, "");

    htmlContent += `
<div class="bullet-item">
  <span class="bullet">•</span>
  <span>${formatInline(item)}</span>
</div>
`;

    continue;
  }


  // ----------------------------------
  // Numbered list
  // ----------------------------------
  if (/^\d+\.\s+/.test(line)) {

    const match = line.match(/^(\d+)\.\s+(.*)$/);

    htmlContent += `
<div class="numbered-item">
  <span class="number">${escapeHtml(match[1])}.</span>
  <span>${formatInline(match[2])}</span>
</div>
`;

    continue;
  }


  // ----------------------------------
  // Normal paragraph
  // ----------------------------------
  htmlContent += `
<p>${formatInline(line)}</p>
`;
}


// ------------------------------------
// Flush final table
// ------------------------------------
if (inTable) {
  flushTable();
}


// ------------------------------------
// Complete HTML document
// ------------------------------------
const html = `
<!DOCTYPE html>

<html>

<head>

<meta charset="UTF-8">

<style>

@page {
  margin: 35px;
}

body {
  font-family: Arial, Helvetica, sans-serif;
  margin: 0;
  line-height: 1.5;
  color: #222;
  font-size: 11pt;
}

h1 {
  text-align: center;
  font-size: 20pt;
  margin-bottom: 30px;
}

h2 {
  font-size: 14pt;
  margin-top: 25px;
  margin-bottom: 10px;
  border-bottom: 2px solid #333;
  padding-bottom: 5px;
}

p {
  margin: 0 0 10px 0;
}

strong {
  font-weight: bold;
}

.bullet-item {
  display: flex;
  margin: 4px 0 4px 15px;
}

.bullet {
  width: 18px;
  flex-shrink: 0;
}

.numbered-item {
  display: flex;
  margin: 4px 0 4px 15px;
}

.number {
  width: 25px;
  flex-shrink: 0;
}


/* -------------------------------
   REAL HTML TABLE
-------------------------------- */

table {
  width: 100%;
  border-collapse: collapse;
  margin: 15px 0 20px 0;
  font-size: 10pt;
  page-break-inside: auto;
}

thead {
  display: table-header-group;
}

tr {
  page-break-inside: avoid;
  page-break-after: auto;
}

th,
td {
  border: 1px solid #555;
  padding: 7px 8px;
  text-align: left;
  vertical-align: top;
}

th {
  font-weight: bold;
  background-color: #eeeeee;
}


/* Keep headings with content */

h2 {
  page-break-after: avoid;
}


/* Avoid ugly paragraph splitting */

p {
  orphans: 3;
  widows: 3;
}

</style>

</head>

<body>

${htmlContent}

</body>

</html>
`;


// ------------------------------------
// Return HTML to next n8n node
// ------------------------------------
return [
  {
    json: {
      html: html
    }
  }
];

// Get the existing PRD from the Data Table

